<?php
namespace App\Http\Controllers\AI;use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Http;
class AIController extends Controller{private function u($r){return $r->attributes->get('legacy_auth_user')->id;}public function analyze(Request $r){$c=$r->input('consultation_id');$i=$r->input('consultation_image_id');if(!$c||!$i)return response()->json(['message'=>'Thiếu thông tin (consultation_id / consultation_image_id)! [v3-AI]'],400);$url=DB::table('consultation_image')->where('id',$i)->where('consultation_id',$c)->value('image_url');if(!$url)return response()->json(['message'=>'Không tìm thấy hình ảnh tương ứng. (E1. Invalid Image)'],404);$id=DB::table('ai_analysis_request')->insertGetId(['consultation_id'=>$c,'consultation_image_id'=>$i,'requested_by'=>$this->u($r),'model_name'=>'Holora-Med-Vision-v1.2','request_type'=>'image_analysis','status'=>'processing']);app()->terminating(function()use($id,$url,$c,$i){try{$p=public_path('uploads/'.basename(parse_url($url,PHP_URL_PATH)));$h=['X-API-Key'=>config('legacy.image_processing.internal_api_key')];$b=Http::timeout(15)->withHeaders($h)->attach('file',fopen($p,'r'),basename($p))->post(rtrim(config('legacy.image_processing.url'),'/').'/api/v1/preprocess',['source_image_id'=>$i,'source_consultation_id'=>$c,'modality'=>'xray','body_part'=>'unspecified'])->json();$job=$b['job_id']??$b['id']??null;$x=$job?Http::timeout(15)->withHeaders($h)->get(rtrim(config('legacy.image_processing.url'),'/').'/api/v1/jobs/'.$job.'/result')->json():$b;DB::table('ai_analysis_result')->insert(['request_id'=>$id,'result_summary'=>$x['resultSummary']??$x['summary']??null,'result_payload'=>json_encode($x),'confidence_score'=>$x['confidenceScore']??null,'risk_level'=>$x['riskLevel']??null,'recommendation'=>$x['recommendation']??null]);DB::table('ai_analysis_request')->where('id',$id)->update(['status'=>'completed','completed_at'=>now()]);}catch(\Throwable $e){DB::table('ai_analysis_request')->where('id',$id)->update(['status'=>'failed','error_message'=>$e->getMessage()]);}});return response()->json(['message'=>'Yêu cầu phân tích AI đã được gửi đi thành công.','analysis_request_id'=>$id,'status'=>'processing'],202);}public function consultation(Request $r,$id){try{$p=$r->attributes->get('legacy_auth_user')->role==='patient';$c=['req.id as request_id','req.consultation_image_id','req.status as request_status','req.requested_at'];if(!$p)$c[]='req.error_message';$c=array_merge($c,['img.image_url','res.result_summary','res.confidence_score','res.risk_level','res.recommendation','res.created_at as completed_at','res.doctor_review_status','res.shared_with_patient','res.review_note','res.result_payload']);$q=DB::table('ai_analysis_request as req')->leftJoin('ai_analysis_result as res','req.id','=','res.request_id')->leftJoin('consultation_image as img','req.consultation_image_id','=','img.id')->where('req.consultation_id',$id);if($p)$q->where('res.shared_with_patient',1);$rows=$q->select($c)->orderBy('req.requested_at','desc')->get();foreach($rows as $x){if(is_string($x->result_payload))$x->result_payload=json_decode($x->result_payload);}return response()->json(['data'=>$rows]);}catch(\Throwable $e){return response()->json(['data'=>[]]);}}public function review(Request $r,$id){$s=$r->input('review_status');if(!in_array($s,['pending_review','approved','approved_watch','not_standard','revoked']))return response()->json(['message'=>'Trạng thái đánh giá không hợp lệ.'],400);$d=DB::table('doctor')->where('user_id',$this->u($r))->value('id');if(!$d&&!in_array($r->attributes->get('legacy_auth_user')->role,['admin','super_admin']))return response()->json(['message'=>'Chỉ bác sĩ mới có quyền đánh giá kết quả AI.'],403);$share=in_array($s,['approved','approved_watch']);$n=DB::table('ai_analysis_result')->where('request_id',$id)->update(['doctor_review_status'=>$s,'shared_with_patient'=>$share,'review_note'=>$r->input('review_note'),'reviewed_by_doctor_id'=>$d,'reviewed_at'=>now()]);return $n?response()->json(['message'=>'Đã lưu đánh giá kết quả AI.','shared_with_patient'=>$share?1:0]):response()->json(['message'=>'Không tìm thấy kết quả AI cần cập nhật.'],404);}}
